#include "modding/ModContent.h"
#include "modding/ContentStorage.h"
#include "modding/ModStore.h"
#include "SceneFingerprint.h"
#include <filesystem>
#include <fstream>
#include <iostream>
using namespace JudasMods;
namespace fs=std::filesystem;
JSON rows=JSON::array(); unsigned failures=0;
void Check(bool value,const std::string& name){rows.push_back({{"name",name},{"passed",value}});std::cout<<(value?"PASS ":"FAIL ")<<name<<'\n';if(!value)++failures;}
Package Fixture(const std::string& id,bool code=false){Package p;p.manifest.id=id;p.manifest.name=id;p.manifest.version="1.0.0";p.manifest.game="audit";p.manifest.gameVersion=p.manifest.contractVersion="1.0.0";p.manifest.author="Audit";p.manifest.license="CC0";p.manifest.executable=code;p.manifest.notices={"NOTICE.txt"};p.files["NOTICE.txt"]="original "+id;p.manifest.files={{"NOTICE.txt",SceneFingerprintSha256(p.files.begin()->second),p.files.begin()->second.size()}};std::string bytes,error;if(!EncodePackage(p,bytes,error)||!DecodePackage(bytes,p,error))throw std::runtime_error(error);return p;}
int main(int argc,char**argv){if(argc!=2)return 2;fs::path root=argv[1];if(fs::exists(root))return 3;fs::create_directories(root);std::string error,read;JSON observations=JSON::object();try{
ContentStorage storage((root/"atomic").string());Check(storage.Publish("index.json","last-good",error),"publish initial mutable file");storage.boundary=[](const char* phase){if(std::string(phase)=="file-synced")throw std::runtime_error("audit interruption before publication");};Check(!storage.Publish("index.json","never-published",error),"injected pre-publication failure reported");Check(storage.Read("index.json",read,256,error)&&read=="last-good","interrupted replacement preserves exact last-good bytes");storage.boundary={};Check(storage.Publish("index.json","next-good",error),"valid replacement after interruption succeeds");Check(storage.Read("index.json",read,256,error)&&read=="next-good","positive replacement changes bytes");Check(!storage.Publish("../outside.txt","escape",error)&&!fs::exists(root/"outside.txt"),"path traversal rejects before external publication");
Contract c;c.enabled=c.executable=true;c.game="audit";c.gameVersion=c.version="1.0.0";c.registries=SceneFingerprintSha256("audit registries");c.additions={"script"};Store store((root/"mods").string()),second((root/"mods").string());auto data=Fixture("data"),code=Fixture("code",true);std::vector<Installed> installed;std::vector<Loadout> selected;
Check(store.Install(c,data,error),"data package installed");Check(store.Enable(c,data.manifest.id,"1.0.0",data.hash,false,error),"data package selected without executable trust");Snapshot active;Check(store.Freeze(c,active,error)&&active.resolution.ordered.size()==1,"ordinary freeze publishes selected data session");auto signature=active.resolution.signature;auto cached=active.files.at("data:NOTICE.txt");std::ifstream in(cached);std::string bytes((std::istreambuf_iterator<char>(in)),{});in.close();Check(bytes==data.files.at("NOTICE.txt"),"frozen cache contains exact decoded payload");Check(second.Disable("data",error),"second store changes next-launch selection");Snapshot future;Check(second.Freeze(c,future,error)&&future.resolution.ordered.empty(),"new session observes disabled selection");Check(active.resolution.signature==signature&&active.resolution.ordered.size()==1,"live snapshot remains fixed after next-launch disable");Check(!second.Remove("data","1.0.0",data.hash,error),"cross-store uninstall blocked by active session lease");observations["leasedRemovalDiagnostic"]=error;Check(fs::exists(cached),"failed uninstall preserves active materialized file");active={};Check(second.Remove("data","1.0.0",data.hash,error),"release session permits uninstall");Check(second.List(installed,selected,error)&&installed.empty()&&selected.empty(),"uninstall leaves consistent empty index and loadout");
Check(store.Install(c,code,error),"executable package can install without starting code");Check(!store.Enable(c,"code","1.0.0",code.hash,false,error),"untrusted executable selection rejected");Check(store.List(installed,selected,error)&&selected.empty(),"trust rejection leaves prior loadout unchanged");Check(store.Enable(c,"code","1.0.0",code.hash,true,error),"exact-hash explicit trust permits executable selection");Snapshot trusted;Check(store.Freeze(c,trusted,error)&&trusted.resolution.ordered.size()==1&&trusted.resolution.ordered[0].trustedHash==code.hash,"frozen executable session retains exact trusted identity");auto denied=c;denied.executable=false;Snapshot sentinel;sentinel.resolution.signature="unchanged-output";Check(!store.Freeze(denied,sentinel,error)&&sentinel.resolution.signature=="unchanged-output","game permission denial leaves caller snapshot unpublished");trusted={};Check(store.Disable("code",error),"disable executable before next package test");auto dependent=Fixture("dependent");dependent.manifest.dependencies={{"data","1.0.0"}};std::string encoded;Check(EncodePackage(dependent,encoded,error)&&DecodePackage(encoded,dependent,error)&&store.Install(c,dependent,error),"install dependent metadata without resolving absent dependency");Check(!store.Enable(c,"dependent","1.0.0",dependent.hash,false,error),"absent dependency blocks selection");Check(store.List(installed,selected,error)&&selected.empty(),"dependency failure cannot publish partial loadout");
auto update=Fixture("update");store.boundary=[](const char*phase){if(std::string(phase)=="package-published")throw std::runtime_error("audit install interruption");};Check(!store.Install(c,update,error),"interruption after immutable payload reports failure");Check(store.List(installed,selected,error)&&installed.size()==2&&selected.empty(),"interruption retains exact previous installed membership");store.boundary={};Check(store.Install(c,update,error),"exact orphan payload reusable after interrupted install");auto cancelled=Fixture("cancelled");Check(!store.Install(c,cancelled,error,[]{return true;}),"pre-publication cancellation rejects install");Check(store.List(installed,selected,error)&&installed.size()==3&&selected.empty(),"cancelled install retains existing index/loadout");
Check(store.Enable(c,"code","1.0.0",code.hash,true,error),"restore positive executable control");Check(store.List(installed,selected,error),"read installed file identities");std::string corruptFile;for(auto&i:installed)if(i.id=="code")corruptFile=i.file;ContentStorage raw((root/"mods"/"Installed").string());Check(raw.Publish(corruptFile,"corrupt payload",error),"audit can deliberately corrupt unleased owned fixture");Snapshot rejected;rejected.resolution.signature="not-replaced";Check(!store.Freeze(c,rejected,error)&&rejected.resolution.signature=="not-replaced","corrupt selected payload fails without replacing output snapshot");observations["corruptFreezeDiagnostic"]=error;
}catch(const std::exception&ex){Check(false,std::string("unexpected exception: ")+ex.what());}
JSON result={{"checks",rows.size()},{"failures",failures},{"assertions",rows},{"observations",observations},{"scope","Native storage/admission/session leases; not JS execution, process crash or complete export integration"}};std::ofstream(root/"RESULT.json")<<result.dump(2)<<'\n';std::cout<<"SUMMARY "<<rows.size()<<" checks / "<<failures<<" failures\n";return failures?1:0;}
